"""V1 Sad adaptation: front droop and two held asymmetric front slumps."""
import json
from motion_core import *
def generate(settings=None):
 cfg=configuration('sad','V1 Sad: low forward droop, pause, asymmetric front slump to one side, pause, opposite front slump, pause, then stand. Source front pairs R1/L1 and R3/L3 change unequally in the two expressive poses; body roll/yaw and all twelve joints recreate that asymmetry.')
 cfg.update(dict(ready_body_mm=[0,0,76],droop_body_mm=[-4,0,69],droop_euler_degrees=[0,10,0],front_slide_mm=8.,left_body_mm=[-4,1,68],left_euler_degrees=[3,10,-2],right_body_mm=[-4,-1,68],right_euler_degrees=[-3,10,2],brace_seconds=.8,droop_seconds=1.,slump_seconds=.7,droop_hold_seconds=.9,slump_hold_seconds=.5,stand_hold_seconds=.5))
 cfg.update(settings or {});m=Motion(cfg);a=m.pose(cfg['ready_body_mm'],[0,0,0],cfg['brace_seconds'],'soften_stance');b=m.pose(cfg['droop_body_mm'],cfg['droop_euler_degrees'],cfg['droop_seconds'],'droop_front',cfg['front_slide_mm']);m.hold(cfg['droop_hold_seconds'],'hold_sad_droop');c=m.pose(cfg['left_body_mm'],cfg['left_euler_degrees'],cfg['slump_seconds'],'left_front_slump');m.hold(cfg['slump_hold_seconds'],'hold_left_slump');m.reverse(c,'center_after_left_slump');d=m.pose(cfg['right_body_mm'],cfg['right_euler_degrees'],cfg['slump_seconds'],'right_front_slump');m.hold(cfg['slump_hold_seconds'],'hold_right_slump');m.reverse(d,'center_after_right_slump');m.reverse(b,'lift_sad_droop');m.reverse(a,'return_to_standing');cfg['face_cues']=[dict(time_s=0,name='sad_motion',mode='once',fps=1),dict(time_s=m.now,name='stand',mode='once',fps=1)];m.hold(cfg['stand_hold_seconds'],'hold_standing');return m.output()
if __name__=='__main__':save(generate(json.loads((P/'config.json').read_text()) if (P/'config.json').exists() else None))
